#!/usr/bin/env bun
/**
 * generate env-server.ts from package.json "env" section.
 *
 * reads package.json "env" object:
 *   - `true` → ensureEnv('KEY')              (required, no default)
 *   - `""` → ensureEnv('KEY', "")            (optional, empty default)
 *   - `"value"` → ensureEnv('KEY', "value")  (optional, has default)
 *   - `"$dep:pkg"` → ensureEnv('KEY')        (version resolved elsewhere, required at runtime)
 *
 * usage: bun @take-out/env/generate [--out path]
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import path from 'node:path'

const BRACKET_NOTATION_KEYS = new Set([
  'ZERO_UPSTREAM_DB',
  'ZERO_CVR_DB',
  'ZERO_CHANGE_DB',
])

const MARKER_START = '// 🔒 start - this is generated by "bun env:update"'
const MARKER_END = '// 🔒 end - this is generated by "bun env:update"'

function escapeRegExp(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

export function generate(opts: { cwd?: string; outPath?: string } = {}) {
  const cwd = opts.cwd || process.cwd()
  const packageJson = JSON.parse(readFileSync(path.join(cwd, 'package.json'), 'utf-8'))
  const envVars = packageJson.env as Record<string, boolean | string> | undefined

  if (!envVars || typeof envVars !== 'object' || Array.isArray(envVars)) {
    console.error('no "env" section found in package.json')
    process.exit(1)
  }

  const lines: string[] = []
  const bracketLines: string[] = []

  for (const [key, value] of Object.entries(envVars)) {
    if (BRACKET_NOTATION_KEYS.has(key)) {
      bracketLines.push(`export const ${key} = process.env['${key}'] || ''`)
      continue
    }

    if (value === true || (typeof value === 'string' && value.startsWith('$dep:'))) {
      lines.push(`export const ${key} = ensureEnv('${key}')`)
    } else {
      lines.push(`export const ${key} = ensureEnv('${key}', ${JSON.stringify(value)})`)
    }
  }

  const generated = lines.join('\n')

  // determine output path
  const outPath =
    opts.outPath ||
    (existsSync(path.join(cwd, 'src/constants'))
      ? 'src/constants/env-server.ts'
      : 'src/server/env-server.ts')

  const fullOutPath = path.join(cwd, outPath)

  let content: string
  if (existsSync(fullOutPath)) {
    content = readFileSync(fullOutPath, 'utf-8')
  } else {
    content = [
      `import { ensureEnv } from '@take-out/env'`,
      ``,
      `if (typeof window !== 'undefined') {`,
      `  throw new Error('env-server.ts must not be imported on the client')`,
      `}`,
      ``,
      MARKER_START,
      MARKER_END,
      ...(bracketLines.length
        ? [
            ``,
            `// database urls - bracket notation prevents build-time inlining`,
            ...bracketLines,
          ]
        : []),
      ``,
    ].join('\n')
  }

  // replace marker section
  if (content.includes(MARKER_START) && content.includes(MARKER_END)) {
    const re = new RegExp(
      `${escapeRegExp(MARKER_START)}[\\s\\S]*?${escapeRegExp(MARKER_END)}`,
    )
    content = content.replace(re, `${MARKER_START}\n${generated}\n${MARKER_END}`)
  }

  mkdirSync(path.dirname(fullOutPath), { recursive: true })

  const existing = existsSync(fullOutPath) ? readFileSync(fullOutPath, 'utf-8') : ''
  if (content !== existing) {
    writeFileSync(fullOutPath, content, 'utf-8')
    console.info(`  env-server.ts updated: ${outPath}`)
  }
}

if (import.meta.main) {
  const outIdx = process.argv.indexOf('--out')
  const outPath = outIdx >= 0 ? process.argv[outIdx + 1] : undefined
  generate({ outPath })
}
